// -------------------------------------------------------------
// FUNGSI MEMBERSIHKAN DUPLIKAT DI FOLDER PEGAWAI
// -------------------------------------------------------------
function handleCleanupDuplicates(data) {
  var rootId = data.parentFolderId || "1hHjdGQPH4HNMuM70ONe3o5ceIdfMWL6O";
  var targetFolder = null;
  var fId = data.folderId;
  if (fId && fId.indexOf("gdrive-") !== 0 && fId.length >= 20) {
    try { targetFolder = DriveApp.getFolderById(fId); } catch (e) {}
  }
  if (!targetFolder && data.employeeName) {
    try {
      var parent = DriveApp.getFolderById(rootId);
      var s = parent.getFoldersByName(data.employeeName.trim());
      if (s.hasNext()) targetFolder = s.next();
    } catch (e) {}
  }
  if (!targetFolder && data.employeeName) {
    try {
      var gs = DriveApp.getFoldersByName(data.employeeName.trim());
      if (gs.hasNext()) targetFolder = gs.next();
    } catch (e) {}
  }

  var trashedCount = 0;
  var trashedNames = [];
  if (targetFolder) {
    var seenNames = {};
    var files = targetFolder.getFiles();
    var filesList = [];
    while (files.hasNext()) {
      var curF = files.next();
      if (!curF.isTrashed()) filesList.push(curF);
    }
    // Urutkan dari yang terbaru: simpan yang terbaru, hapus duplikat lama
    filesList.sort(function(a, b) {
      return b.getLastUpdated().getTime() - a.getLastUpdated().getTime();
    });
    for (var i = 0; i < filesList.length; i++) {
      var f = filesList[i];
      var fName = f.getName().toLowerCase();
      if (seenNames[fName]) {
        var tOk = false;
        try {
          f.setTrashed(true);
          tOk = true;
          trashedCount++;
          trashedNames.push(f.getName());
        } catch (err) {}
        if (!tOk) {
          try {
            targetFolder.removeFile(f);
            trashedCount++;
            trashedNames.push(f.getName());
          } catch(rmErr) {}
        }
      } else {
        seenNames[fName] = true;
      }
    }
  }

  return {
    status: "success",
    trashedCount: trashedCount,
    trashedNames: trashedNames,
    folderName: targetFolder ? targetFolder.getName() : ""
  };
}

// -------------------------------------------------------------
// FUNGSI BUAT ATAU AMBIL FOLDER PEGAWAI DI GOOGLE DRIVE
// -------------------------------------------------------------
function handleCreateEmployeeFolder(data) {
  var defaultRootId = "1hHjdGQPH4HNMuM70ONe3o5ceIdfMWL6O";
  var rootId = data.parentFolderId || defaultRootId;
  var parentFolder;
  try {
    parentFolder = DriveApp.getFolderById(rootId);
  } catch (err) {
    parentFolder = DriveApp.getRootFolder();
  }

  var empName = (data.employeeName || "Pegawai").trim();
  var search = parentFolder.getFoldersByName(empName);
  var empFolder = null;
  if (search.hasNext()) {
    empFolder = search.next();
  } else {
    empFolder = parentFolder.createFolder(empName);
    var desc = "Folder Berkas SIMPEG Bawaslu Kuansing - " + empName;
    if (data.nip) desc += " (NIP: " + data.nip + ")";
    empFolder.setDescription(desc);
    try {
      empFolder.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
    } catch (shErr) {}
  }

  return {
    status: "success",
    folderId: empFolder.getId(),
    folderUrl: empFolder.getUrl(),
    folderName: empFolder.getName()
  };
}

// -------------------------------------------------------------
// FUNGSI PENGHAPUSAN FOLDER PEGAWAI DI GOOGLE DRIVE (SAMPAH / TRASH)
// Dipanggil otomatis saat nama/data pegawai dihapus dari aplikasi SIMPEG
// -------------------------------------------------------------
function handleDeleteEmployeeFolder(data) {
  var defaultRootId = "1hHjdGQPH4HNMuM70ONe3o5ceIdfMWL6O";
  var rootId = data.parentFolderId || defaultRootId;
  var fId = data.folderId || "";
  var empName = (data.employeeName || "").trim();
  var targetFolder = null;
  var deleted = false;
  var folderName = empName;

  // 1. Bersihkan ID folder jika dikirim dalam format URL/link
  if (fId && fId.indexOf("drive.google.com") > -1) {
    var parts = fId.split("/");
    for (var i = 0; i < parts.length; i++) {
      var seg = parts[i].split("?")[0].split("&")[0];
      if (seg.length >= 25 && seg.indexOf("folders") === -1) {
        fId = seg;
        break;
      }
    }
  }

  // 2. Cari target folder jika fId valid
  if (fId && fId.indexOf("gdrive-") !== 0 && fId.length >= 20) {
    try {
      targetFolder = DriveApp.getFolderById(fId);
    } catch(err) {}
  }

  // 3. Jika folder belum ditemukan, cari di dalam folder induk (FILE ARSIP PEGAWAI)
  if (!targetFolder && empName) {
    try {
      var rootFolder;
      try {
        rootFolder = DriveApp.getFolderById(rootId);
      } catch (rfErr) {
        rootFolder = DriveApp.getRootFolder();
      }

      var searchName = rootFolder.getFoldersByName(empName);
      if (searchName.hasNext()) {
        targetFolder = searchName.next();
      } else {
        // Cari subfolder di root yang namanya mirip (case-insensitive)
        var subFolders = rootFolder.getFolders();
        var empClean = empName.toLowerCase().replace(/[^a-z0-9]/g, "");
        while (subFolders.hasNext()) {
          var sf = subFolders.next();
          var sfClean = sf.getName().toLowerCase().replace(/[^a-z0-9]/g, "");
          if (sfClean === empClean || sfClean.indexOf(empClean) > -1 || empClean.indexOf(sfClean) > -1) {
            targetFolder = sf;
            break;
          }
        }
      }
    } catch(err) {}
  }

  // 4. Jika masih belum ditemukan, cari secara global di seluruh Google Drive
  if (!targetFolder && empName) {
    try {
      var globalSearch = DriveApp.getFoldersByName(empName);
      if (globalSearch.hasNext()) {
        targetFolder = globalSearch.next();
      }
    } catch(err) {}
  }

  // 5. PINDAHKAN FOLDER BESERTA SELURUH ISINYA KE SAMPAH (TRASH)
  if (targetFolder) {
    folderName = targetFolder.getName();
    try {
      // Pindahkan folder ke Sampah Google Drive
      targetFolder.setTrashed(true);
      deleted = true;
    } catch(tErr) {
      // Fallback 1: Lepaskan dari folder induk jika setTrashed dibatasi izin
      try {
        var parentF = DriveApp.getFolderById(rootId);
        parentF.removeFolder(targetFolder);
        deleted = true;
      } catch(rfErr) {}

      // Fallback 2: Pindahkan seluruh file di dalamnya ke Sampah
      try {
        var innerFiles = targetFolder.getFiles();
        while (innerFiles.hasNext()) {
          var inf = innerFiles.next();
          try { inf.setTrashed(true); } catch(e) {}
        }
        targetFolder.setName("[TERHAPUS] " + folderName);
        deleted = true;
      } catch(renErr) {}
    }
  }

  return {
    status: "success",
    deleted: deleted,
    folderFound: !!targetFolder,
    folderId: targetFolder ? targetFolder.getId() : fId,
    folderName: folderName,
    message: deleted 
      ? ("Folder Google Drive " + folderName + " berhasil dipindahkan ke Sampah.")
      : (targetFolder ? "Gagal memindahkan folder ke sampah." : "Folder pegawai tidak ditemukan di Google Drive.")
  };
}

